target.css:
:root {
  --ink: #17253d;
  --paper: #ffffff;
  --navy: #213b66;
  --blue: #3569c8;
  --sky: #e9f1ff;
  --line: #d6e0ef;
  --muted: #66758d;
  --lime: #b9e447;
  --lime-ink: #355000;
  --soft: #f7faff;
}

* {
  box-sizing: border-box;
}

.ballot-board {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.board-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.eyebrow {
  margin: 0;
  color: var(--blue);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
  line-height: 1;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 21px;
  font-weight: 750;
  letter-spacing: -0.5px;
  line-height: 1.1;
}

.status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--sky);
  color: var(--navy);
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
}

.status i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--lime);
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 12px 18px;
}

.metric {
  display: flex;
  min-height: 72px;
  flex-direction: column;
  justify-content: space-between;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--soft);
}

.metric > span,
.metric small {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.15;
}

.metric strong {
  color: var(--navy);
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -0.6px;
  line-height: 1;
}

.accent-metric {
  border-color: var(--lime);
  background: var(--lime);
}

.accent-metric > span,
.accent-metric small,
.accent-metric strong {
  color: var(--lime-ink);
}

.progress-panel {
  margin: 0 18px;
  padding: 12px;
  border-radius: 11px;
  background: var(--navy);
}

.progress-copy {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.progress-copy h2 {
  color: var(--paper);
  font-size: 13px;
  font-weight: 750;
  line-height: 1.1;
}

.progress-copy p {
  margin-top: 3px;
  color: var(--sky);
  font-size: 10px;
  line-height: 1;
}

.progress-copy > strong {
  color: var(--lime);
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.meter {
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--blue);
}

.meter span {
  display: block;
  width: 88%;
  height: 100%;
  border-radius: inherit;
  background: var(--lime);
}

.board-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 18px 15px;
}

.board-footer p {
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
}

.board-footer b {
  color: var(--blue);
  font-size: 12px;
}

button {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border: 1px solid var(--navy);
  border-radius: 8px;
  background: var(--paper);
  color: var(--navy);
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
}

button span {
  color: var(--blue);
  font-size: 15px;
  line-height: 0;
}

